mapper.select:
SELECT v.id, v.name, v.brand, COUNT(o.id) as sales_count, SUM(o.amount) as total_amount FROM carsale_vehicle v INNER JOIN carsale_orders o ON v.id = o.vehicle_id WHERE o.status IN (1, 2, 3)
AND o.create_time >= #{startTime}
AND o.create_time <= #{endTime}
GROUP BY v.id, v.name, v.brand ORDER BY sales_count DESC LIMIT 5

SELECT COALESCE(SUM(amount), 0) as total_amount
FROM carsale_orders
WHERE status IN (1, 2, 3)

    AND create_time >= #{startTime}


    AND create_time <= #{endTime}

SELECT COUNT(*) as user_count
FROM sys_user
WHERE del_flag = '0'

    AND create_time >= #{startTime}


    AND create_time <= #{endTime}

SELECT
    v.brand,
    COUNT(o.id) as sales_count,
    SUM(o.amount) as total_amount,
    ROUND(COUNT(o.id) * 100.0 / (SELECT COUNT(*) FROM carsale_orders WHERE status IN (1, 2, 3)

            AND create_time >= #{startTime}


            AND create_time <= #{endTime}

    ), 2) as percentage
FROM carsale_vehicle v
INNER JOIN carsale_orders o ON v.id = o.vehicle_id
WHERE o.status IN (1, 2, 3)

    AND o.create_time >= #{startTime}


    AND o.create_time <= #{endTime}

GROUP BY v.brand
ORDER BY sales_count DESC

SELECT CASE WHEN v.range_km < 400 THEN '<400km' WHEN v.range_km >= 400 AND v.range_km < 600 THEN '400-600km' WHEN v.range_km >= 600 AND v.range_km < 800 THEN '600-800km' ELSE '>=800km' END as range_category, COUNT(o.id) as sales_count, SUM(o.amount) as total_amount, ROUND(COUNT(o.id) * 100.0 / (SELECT COUNT(*) FROM carsale_orders WHERE status IN (1, 2, 3)
AND create_time >= #{startTime}
AND create_time <= #{endTime}
), 2) as percentage FROM carsale_vehicle v INNER JOIN carsale_orders o ON v.id = o.vehicle_id WHERE o.status IN (1, 2, 3)
AND o.create_time >= #{startTime}
AND o.create_time <= #{endTime}
GROUP BY range_category ORDER BY sales_count DESC
